using System;using System.Collections.Generic;
namespace Exoduser.UnityPort.Core {
 public sealed class BladePath {public string Kind,Color;public double Alpha,Width;public bool Round;public double[] Points;}
 public sealed class BladeVisualInput {public string Kind;public double Time,X,Y,Fade=1;public bool Fused;public double[][] Trail=new double[0][];}
 public static class PlayerBladeVisuals {
  public static List<BladePath> Build(BladeVisualInput p){var output=new List<BladePath>();double t=p.Time,fa=p.Fade;Action<string,string,double,double,bool,double[]> add=(k,c,a,w,r,pts)=>output.Add(new BladePath{Kind=k,Color=c,Alpha=a,Width=w,Round=r,Points=pts});Action<string,double,double[]> poly=(c,a,v)=>add("fill",c,a,0,false,v);Action<string,double,double,bool,double[]> line=(c,a,w,r,v)=>add("stroke",c,a,w,r,v);Action<string,double,double,double,double,double> ellipse=(c,a,x,y,rx,ry)=>add("ellipse",c,a,0,false,new[]{x,y,rx,ry});
   if(p.Kind=="venom"){double pulse=.85+Math.Sin(t/60+p.X*.2)*.15;poly("#22cc44",fa*.9*pulse,new double[]{22,0,1,-2,-8,0,1,2});poly("#88ff44",fa*.4,new double[]{18,0,2,-1,-4,0,2,1});line("#aaffaa",fa*.25,.8,false,new double[]{-6,0,20,0});for(int i=0;i<p.Trail.Length;i++){double f=1-i/(double)p.Trail.Length,s=f*.4,x=p.Trail[i][0],y=p.Trail[i][1];poly("#44dd44",fa*f*.2,new[]{x+8*s,y,x-5*s,y-s,x-5*s,y+s});}}
   else if(p.Kind=="lightning"){double pulse=.7+Math.Sin(t/25+p.X*.5)*.3;var pts=new double[14];pts[0]=-10;for(int i=1;i<=6;i++){pts[i*2]=i*(56.0/6)-10;pts[i*2+1]=(i%2==1?1:-1)*(2+Math.Sin(t*.09+p.Y*.3+i*2.1)*3);}line("#2244ff",fa*.12*pulse,12,true,pts);line("#4499ff",fa*.85*pulse,3.5,true,pts);line("#eef4ff",fa*.95,1.2,true,pts);for(int i=2;i<=6;i+=2){double x=pts[i*2],y=pts[i*2+1],d=(i&2)!=0?1:-1;line("#88bbff",fa*.4*pulse,1,true,new[]{x,y,x+4,y+d*(4+Math.Sin(t*.12+i)*2),x+8,y+d*(2+Math.Sin(t*.08+i*3)*1.5)});}ellipse("#88ccff",fa*.5*pulse,46,0,4+Math.Sin(t*.07)*1.5,4+Math.Sin(t*.07)*1.5);ellipse("#eeffff",fa*.9,46,0,1.8,1.8);for(int i=0;i<p.Trail.Length;i+=2){double f=1-i/(double)p.Trail.Length,x=p.Trail[i][0],y=p.Trail[i][1];line("#4488ff",fa*f*.2,1.5,true,new[]{x,y,x-4,y+((i&2)!=0?-3:3)*f,x-8,y});}}
   else if(p.Kind=="blade"){poly(p.Fused?"#ddeeff":"#ccccdd",fa*.95,new double[]{24,0,2,-2.5,-10,0,2,2.5});line("#ffffff",fa*.5,.8,false,new double[]{24,0,2,-2.5,-10,0});line(p.Fused?"#aaccff":"#ddddee",fa*.3,1.2,false,new double[]{-8,0,22,0});for(int i=0;i<p.Trail.Length;i++){double f=1-i/(double)p.Trail.Length,s=f*.5,x=p.Trail[i][0],y=p.Trail[i][1];poly(p.Fused?"#aabbcc":"#bbbbcc",fa*f*.25,new[]{x+10*s,y,x-6*s,y-1.5*s,x-6*s,y+1.5*s});}}
   else if(p.Kind=="plague"){double pulse=.8+Math.Sin(t/50+p.X*.3)*.2;ellipse("#ff0000",fa*.12*pulse,0,0,28,10);ellipse("#ff2200",fa*.2,0,0,20,6);poly("#ff2200",fa*.95,new double[]{24,0,2,-2.5,-10,0,2,2.5});line("#ff4400",fa*.6,1.2,false,new double[]{-8,0,22,0});ellipse("#ffccaa",fa*.7,20,0,1.5,1.5);for(int i=0;i<p.Trail.Length;i++){double f=1-i/(double)p.Trail.Length,s=f*.5,x=p.Trail[i][0],y=p.Trail[i][1];ellipse("#ff0000",fa*f*.2,x,y,8*s,3*s);poly("#ff2200",fa*f*.35,new[]{x+10*s,y,x-6*s,y-1.5*s,x-6*s,y+1.5*s});}}
   return output;
  }
 }
}
